sys_script_include.script:
var DiagnosticsCommonUtil = Class.create();
DiagnosticsCommonUtil.prototype = {
    initialize: function() {
    },

	groupTasks: function(tasks, prefix, suffix) {
		var message = [];
		var noOfGroups = tasks.length/ADTConstants.SYS_IDS_IN_A_GROUP;
		if(noOfGroups > 0){
			var chuncks = [];
			for(var i=0;i<tasks.length;i+=ADTConstants.SYS_IDS_IN_A_GROUP){
				chuncks.push(tasks.slice(i,i+ADTConstants.SYS_IDS_IN_A_GROUP));
			}
			for(var i=0; i<chuncks.length; i++){
				var query = prefix + '' + chuncks[i].join() + '' + suffix;
				message.push(query);
			}
		}
		return message;
	},

    type: 'DiagnosticsCommonUtil'
};
